<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<title>快送外卖 - 我的订单</title>
<style>
body {font-family: Arial, sans-serif; margin:0; padding:0; background:#f9f9f9; color:#333; line-height:1.6;}
header {background:#004d40; color:#fff; padding:10px 20px; display:flex; justify-content:space-between; align-items:center;}
.logo {font-size:1.5em; font-weight:bold;}
nav a {color:#fff; margin-left:15px; text-decoration:none;}
nav a:hover {text-decoration:underline;}
main {max-width:1440px; margin:auto; padding:20px;}
.order-summary h2 {margin-bottom:20px; font-size:1.8em; color:#00695c;}
.order-item {display:flex; justify-content:space-between; margin:5px 0; font-size:0.95em;}
.order-item .price {font-weight:bold; color:#d32f2f;}
footer {text-align:center; padding:10px; margin-top:30px; font-size:0.9em; color:#777; background:#e0e0e0;}
</style>
</head>
<body>
<header>
<div class="logo">快送外卖</div>
<nav>
<a href="index.html">首页</a>
<a href="about.html">关于我们</a>
<a href="restaurant-list.html">餐厅列表</a>
<a href="restaurant-page.html">餐厅页面</a>
</nav>
</header>

<main>
<section class="order-summary">
<h2>订单摘要</h2>
<div id="order-items"></div>
<p>总价: <span id="total-price">￥0</span></p>
<button id="submit-btn">提交订单</button>
</section>
</main>

<footer>
<p>&copy; 2025 快送外卖</p>
</footer>

<script>
document.addEventListener('DOMContentLoaded', () => {
 const cart = JSON.parse(localStorage.getItem('cart')) || [];
 const listDiv = document.getElementById('order-items');
 let total = 0;
 cart.forEach(item => {
 const div = document.createElement('div');
 div.className = 'order-item';
 div.innerHTML = `<span>${item.name}</span><span class="price">￥${item.price}</span>`;
 listDiv.appendChild(div);
 total += item.price;
 });
 document.getElementById('total-price').textContent = '￥' + total;
 document.getElementById('submit-btn').addEventListener('click', () => {
 alert('订单已提交，感谢您的惠顾！');
 });
});
</script>
</body>
</html>
